// Socket.io客户端库 (简化版)
// 这是一个简化的Socket.io客户端实现，适用于微信小程序

(function() {
  'use strict';

  function Socket(url, options) {
    this.url = url;
    this.options = options || {};
    this.connected = false;
    this.events = {};
    this.socket = null;
    this.reconnectAttempts = 0;
    this.maxReconnectAttempts = 5;
    this.reconnectDelay = 1000;
    
    this.connect();
  }

  Socket.prototype.connect = function() {
    const self = this;
    
    try {
      this.socket = wx.connectSocket({
        url: this.url,
        protocols: ['websocket']
      });

      this.socket.onOpen(function() {
        console.log('WebSocket连接成功');
        self.connected = true;
        self.reconnectAttempts = 0;
        self.emit('connect');
      });

      this.socket.onClose(function() {
        console.log('WebSocket连接关闭');
        self.connected = false;
        self.emit('disconnect');
        
        // 自动重连
        if (self.reconnectAttempts < self.maxReconnectAttempts) {
          setTimeout(function() {
            self.reconnectAttempts++;
            self.connect();
          }, self.reconnectDelay * self.reconnectAttempts);
        }
      });

      this.socket.onError(function(error) {
        console.error('WebSocket连接错误:', error);
        self.emit('error', error);
      });

      this.socket.onMessage(function(res) {
        try {
          const data = JSON.parse(res.data);
          if (data.type) {
            self.emit(data.type, data.data);
          }
        } catch (e) {
          console.error('解析消息失败:', e);
        }
      });

    } catch (error) {
      console.error('创建WebSocket连接失败:', error);
      this.emit('error', error);
    }
  };

  Socket.prototype.emit = function(event, data) {
    if (this.connected && this.socket) {
      const message = {
        type: event,
        data: data
      };
      this.socket.send({
        data: JSON.stringify(message)
      });
    }
  };

  Socket.prototype.on = function(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  };

  Socket.prototype.off = function(event, callback) {
    if (this.events[event]) {
      this.events[event] = this.events[event].filter(cb => cb !== callback);
    }
  };

  Socket.prototype.emit = function(event, data) {
    // 触发事件
    if (this.events[event]) {
      this.events[event].forEach(callback => {
        try {
          callback(data);
        } catch (e) {
          console.error('事件回调执行失败:', e);
        }
      });
    }

    // 发送消息到服务器
    if (this.connected && this.socket) {
      const message = {
        type: event,
        data: data
      };
      this.socket.send({
        data: JSON.stringify(message)
      });
    }
  };

  Socket.prototype.disconnect = function() {
    if (this.socket) {
      this.socket.close();
    }
  };

  // 导出Socket构造函数
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = Socket;
  } else {
    window.io = function(url, options) {
      return new Socket(url, options);
    };
  }

})();